dt-example.css:
div.demo-html > button {
	margin-bottom: 0.5em;
}

div.demo-html > ul button {
	margin-left: 0.5em;
	margin-bottom: 0.5em;
}

dt-example.js:
const Dom = DataTable.Dom;
const states = Dom.s('#states');

function populateStateList(table, statesEl) {
	statesEl.empty();

	table.stateRestore
		.states()
		.details()
		.forEach(s => {
			Dom.c('li')
				.text(s.name)
				.attr('data-state-id', s.id)
				.append(Dom.c('button').classAdd('load').text('Load'))
				.append(Dom.c('button').classAdd('edit').text('Edit'))
				.append(Dom.c('button').classAdd('replace').text('Replace'))
				.append(Dom.c('button').classAdd('remove').text('Remove'))
				.appendTo(statesEl);
		});
}

// Create the DataTable - regular StateRestore buttons are included to show the interaction
const table = new DataTable('#example', {
	layout: {
		topStart: {
			buttons: ['stateCreate', 'statesList', 'pageLength']
		}
	},
	stateRestore: true
});

// List of states - updates based on the `stateRestore` event
table.on('stateRestore', () => populateStateList(table, states));

// Initial population
populateStateList(table, states);

// Event handlers
Dom.s('#add').on('click', function () {
	table.stateRestore.add();
});

Dom.s('#deleteAll').on('click', function () {
	table.stateRestore.states().remove();
});

states.on('click', 'button.load', function () {
	table.stateRestore
		.state(this.parentNode.getAttribute('data-state-id'))
		.load();
});

states.on('click', 'button.edit', function () {
	table.stateRestore
		.state(this.parentNode.getAttribute('data-state-id'))
		.edit();
});

states.on('click', 'button.replace', function () {
	table.stateRestore
		.state(this.parentNode.getAttribute('data-state-id'))
		.save();
});

states.on('click', 'button.remove', function () {
	table.stateRestore
		.state(this.parentNode.getAttribute('data-state-id'))
		.remove();
});
